function getSetCookies(headers) {
  if (typeof headers.getSetCookie === 'function') {
    return headers.getSetCookie();
  }
  const single = headers.get('set-cookie');
  return single ? [single] : [];
}

class CookieJar {
  constructor() {
    this.cookies = new Map();
  }

  setFromResponse(headers) {
    for (const entry of getSetCookies(headers)) {
      const first = String(entry || '').split(';')[0];
      const idx = first.indexOf('=');
      if (idx <= 0) continue;
      const name = first.slice(0, idx).trim();
      const value = first.slice(idx + 1).trim();
      if (!name) continue;
      this.cookies.set(name, value);
    }
  }

  header() {
    return [...this.cookies.entries()].map(([name, value]) => `${name}=${value}`).join('; ');
  }
}

function parseCsrfToken(html) {
  const inputMatch = String(html || '').match(/name="csrf_token"\s+type="hidden"\s+value="([^"]+)"/i);
  if (inputMatch) return inputMatch[1];
  const metaMatch = String(html || '').match(/<meta\s+name="csrf-token"\s+content="([^"]+)"/i);
  return metaMatch ? metaMatch[1] : '';
}

function toKstDateParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const pick = (type) => parts.find((part) => part.type === type)?.value || '';
  return {
    year: Number(pick('year')),
    month: Number(pick('month')),
    day: Number(pick('day')),
  };
}

function toKstTimestamp(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const pick = (type) => parts.find((part) => part.type === type)?.value || '';
  return `${pick('year')}-${pick('month')}-${pick('day')} ${pick('hour')}:${pick('minute')}:${pick('second')} KST`;
}

function toKstDate(date = new Date()) {
  const parts = toKstDateParts(date);
  return `${String(parts.year).padStart(4, '0')}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
}

function addMonthsKeepingDay(date, months) {
  const next = new Date(date.getTime());
  next.setUTCMonth(next.getUTCMonth() + months);
  return next;
}

function buildSyncWindow() {
  const today = new Date();
  const startDate = toKstDate(today);
  const endDate = toKstDate(addMonthsKeepingDay(today, 1));
  const startParts = toKstDateParts(today);
  const endParts = toKstDateParts(addMonthsKeepingDay(today, 1));
  const pairSet = new Set([
    `${startParts.year}-${startParts.month}`,
    `${endParts.year}-${endParts.month}`,
  ]);
  const monthPairs = [...pairSet].map((value) => {
    const [year, month] = value.split('-').map(Number);
    return { year, month };
  }).sort((a, b) => {
    if (a.year !== b.year) return a.year - b.year;
    return a.month - b.month;
  });

  return {
    startDate,
    endDate,
    monthPairs,
